from model import Summary


def run(jobs, budget):
    ordered_jobs = sorted(jobs, key=lambda job: job.id)
    completed = set()
    order = []
    remaining = budget

    while True:
        for job in ordered_jobs:
            if job.id in completed or job.cost > remaining:
                continue
            if not all(dependency in completed for dependency in job.deps):
                continue
            completed.add(job.id)
            order.append(job.id)
            remaining -= job.cost
            break
        else:
            break

    return Summary(order, budget - remaining, len(jobs) - len(completed))

